<script setup lang="ts">
import { t as uiText } from '@/locales'

import {onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import PageContainer from '@/components/PageContainer/index.vue'
import {listedCatalogPage,operationTarget} from '@/api/modules/partnerOperations'
import {partnerError} from '@/utils/partnerError'
import type {ListedCatalogRow} from '@/types/partnerLifecycle'
import PartnerPhoto from '../PartnerPhoto.vue'
import {catalogPhoneSummary} from '../catalog/catalogPresentation'
const route=useRoute(),router=useRouter(),status=ref<'listed'|'pending'|'unlisted'|'all'>('listed'),keyword=ref(''),page=ref(1),total=ref(0),rows=ref<ListedCatalogRow[]>([]),loading=ref(false),error=ref('')
const labels={listed:'已上架',pending:'待上架',unlisted:'已下架',all:'全部'} as const
let generation=0
async function load(){const serial=++generation;loading.value=true;error.value='';try{const data=await listedCatalogPage({status:status.value,keyword:keyword.value.trim(),page:page.value,size:30});if(serial!==generation)return;rows.value=data.content;total.value=data.totalElements}catch(e){if(serial===generation)error.value=partnerError(e)}finally{if(serial===generation)loading.value=false}}
watch(()=>route.fullPath,()=>{const query=String(route.query.status||'listed');status.value=query in labels?query as typeof status.value:'listed';keyword.value=String(route.query.keyword||'');page.value=Math.max(1,Number(route.query.page)||1);void load()},{immediate:true})
onBeforeUnmount(()=>{generation++})
function search(){void router.replace({path:'/partner-listings',query:{status:status.value,keyword:keyword.value.trim()||undefined,page:1}})}
function open(row:ListedCatalogRow){if(row.legacyProduct&&row.productId)void router.push({path:'/partner-products',query:{id:row.productId,from:route.fullPath}});else if(row.listingId)void router.push(operationTarget('listing',row.listingId,route.fullPath));else if(row.productId)void router.push({path:'/partner-products',query:{id:row.productId,from:route.fullPath}})}
const state=(row:ListedCatalogRow)=>labels[row.status as keyof typeof labels]||'待上架'
</script>
<template><PageContainer :title='uiText("上架产品目录")' class="listed-catalog"><template #actions><el-button @click="router.push('/partner-selections')">{{ uiText("选品目录") }}</el-button><el-button :loading="loading" @click="load">{{ uiText("刷新") }}</el-button></template><div class="listed-filter"><el-radio-group v-model="status" @change="search"><el-radio-button v-for="(label,value) in labels" :key="value" :value="value">{{label}}</el-radio-button></el-radio-group><el-input v-model="keyword" clearable :placeholder='uiText("搜索商品、款式号或手机型号")' @keyup.enter="search"/><el-button @click="search">{{ uiText("查询") }}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">{{ uiText("重试") }}</el-button></el-alert><div class="listed-scroll" v-loading="loading"><div class="listed-head"><span>{{ uiText("图片") }}</span><span>{{ uiText("款式号／商品名称") }}</span><span>{{ uiText("经营手机型号") }}</span><span>{{ uiText("颜色") }}</span><span>{{ uiText("上架状态") }}</span><span>{{ uiText("渠道") }}</span><span>{{ uiText("操作") }}</span></div><article v-for="row in rows" :key="(row.listingId?'listing:':'product:')+(row.listingId||row.productId||row.id)" class="listed-row"><div class="listed-photo"><PartnerPhoto v-if="row.photoId" :id="row.photoId" :allow-retry="true"/><span v-else>{{ uiText("暂无图片") }}</span></div><div class="listed-name"><small>{{row.catalogStyleLabel||row.catalogStyleCode||row.code}}</small><strong>{{row.name}}</strong></div><div class="listed-models"><span class="field-label">{{ uiText("手机型号") }}</span><strong>{{row.phones?.length?catalogPhoneSummary(row):uiText('见经营规格')}}</strong><small v-if="(row.phones?.length||0)>2">{{ uiText("另有 ") }}{{(row.phones?.length||0)-1}}{{ uiText(" 个型号 · 详情查看") }}</small></div><div class="listed-color"><span class="field-label">{{ uiText("颜色") }}</span>{{row.color||uiText('见经营规格')}}</div><div class="listed-status"><el-tag :type="row.status==='listed'?'success':row.status==='unlisted'?'info':'warning'">{{state(row)}}</el-tag><small v-if="row.integrationStatus==='not_connected'">{{ uiText("未接通") }}</small></div><div class="listed-channel"><span class="field-label">{{ uiText("渠道") }}</span>{{row.channel||uiText('未记录')}}</div><div class="listed-actions"><el-button link type="primary" @click="open(row)">{{ uiText("查看依据") }}</el-button></div></article><el-empty v-if="!loading&&!rows.length" :description="status==='listed'?uiText('暂无已上架商品；未接通的准备记录可切到待上架查看'):uiText('当前范围暂无记录')"/></div><footer><span>{{ uiText("共") }}{{total}}{{ uiText("条") }}</span><el-pagination :current-page="page" :page-size="30" :total="total" :pager-count="5" layout="prev,pager,next" @current-change="router.replace({path:'/partner-listings',query:{...route.query,page:$event}})"/></footer></PageContainer></template>
<style scoped>
.listed-catalog{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;container-type:inline-size}.listed-catalog :deep(>.page-panel){padding:6px 10px;flex:none}.listed-catalog :deep(.page-panel-header){margin:0;align-items:center;flex-direction:row;flex-wrap:wrap}.listed-catalog :deep(.page-panel-title){font-size:17px}.listed-filter{display:flex;align-items:center;gap:7px;flex-wrap:wrap;flex:none}.listed-filter>.el-input{flex:1;min-width:180px}.listed-scroll{flex:1;min-height:0;min-width:0;overflow-y:auto;border:1px solid var(--el-border-color-lighter);border-radius:5px;background:white}.listed-head,.listed-row{display:grid;grid-template-columns:60px minmax(0,1.2fr) minmax(0,1.6fr) minmax(0,1fr) 100px minmax(0,.8fr) 88px}.listed-head{position:sticky;top:0;background:var(--el-fill-color-light);font-size:12px;color:var(--el-text-color-secondary)}.listed-head>span,.listed-row>div{padding:4px 8px;min-width:0;overflow-wrap:anywhere}.listed-row{min-height:52px;border-top:1px solid var(--el-border-color-lighter);font-size:13px;line-height:1.5;align-items:center}.listed-name,.listed-models{display:flex;flex-direction:column}.listed-name small,.listed-row small{display:block;color:var(--el-text-color-secondary);font-size:12px;line-height:1.5}.listed-models strong{font-size:15px;color:#284d7c}.listed-photo :deep(.partner-photo){width:44px;height:44px}.listed-photo>span{font-size:12px;color:var(--el-text-color-secondary)}.field-label{display:none}.listed-actions :deep(.el-button){white-space:normal;height:auto;padding:0;max-width:100%;line-height:1.5}.listed-catalog footer{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px;flex:none}
@container(max-width:900px){.listed-head{display:none}.listed-row{display:grid;grid-template-columns:44px minmax(0,1.1fr) minmax(0,.8fr) minmax(0,1.1fr) minmax(0,.7fr) 72px;grid-template-rows:auto auto;padding:5px 6px;gap:1px 7px}.listed-row>div{padding:0}.listed-photo{grid-column:1;grid-row:1/3;align-self:start;margin-top:3px}.listed-name{grid-column:2/4;grid-row:1}.listed-models{grid-column:4/6;grid-row:1}.listed-models>.field-label{display:none}.listed-color{grid-column:2/4;grid-row:2}.listed-status{grid-column:4;grid-row:2}.listed-channel{grid-column:5;grid-row:2}.listed-actions{grid-column:6;grid-row:1/3}.field-label{display:inline;color:var(--el-text-color-secondary);margin-right:5px;font-size:12px}}
@container(max-width:480px){.listed-row{grid-template-columns:44px minmax(0,1fr) minmax(0,1fr) 64px}.listed-name{grid-column:2/4;grid-row:1}.listed-models{grid-column:2/4;grid-row:2}.listed-color{grid-column:2;grid-row:3}.listed-status{grid-column:3;grid-row:3}.listed-channel{grid-column:2/4;grid-row:4}.listed-actions{grid-column:4;grid-row:1/4}}
</style>
